window.NW_CONFIG = {"city": {"name": "NW Digital City", "scope_label": "Vodafone Networks, Level 1 \"Network\"", "agent_name": "Crane", "vest_mark": "data:image/png;base64,"}, "street_life": {"metric": "total", "quiet": 0.4, "busy": 2.4, "vehicles": 58, "cyclists": 20, "people": 140, "standing": 0.55, "cluster_max": 4, "four_lane_above": 0.55, "on_streets": 0.2, "built_bias": 0.7}, "layers": {"foundation": {"metric": "blueprint_state", "caption": "Whether the category rules have been captured", "detail": "A lot with no blueprint is bare ground. A drafted one is marked out in yellow and carries a faint outline of the building that could stand there. An active one has foundations laid, and only then can anything be built on it."}, "height": {"metric": "journey_score", "caption": "How far along the journey it has got", "detail": "40 points for writing the blueprint, 35 for anybody using it, 25 for doing it with AI. Height rises only once a foundation is laid, so a drafted lot shows an outline rather than a building. Past the landmark threshold the building is replaced by a monument."}, "value": {"metric": "spend_eur", "caption": "Commercial scale of sourcing activity", "detail": "Houses on the front of the lot, then a hotel, on the Monopoly ladder. Four houses become one hotel, and the hotel is the same width as the four it replaces, so the upgrade reads as an upgrade. This is the one layer that has nothing to do with progress: the money is recorded whether or not a blueprint exists, so a lot can carry a hotel on bare ground. A311 does, and it is the largest empty lot in the estate."}, "occupancy": {"metric": "cbp_used", "caption": "Whether anybody has used the blueprint", "detail": "A used lot keeps its colour and lights its windows. An unused one is drained to grey with the windows dark. A monument follows the same rule: washed out if unused, floodlit after dark if used. This is the loudest thing in the city, because 52 of the 56 built lots are drained."}, "reactor": {"metric": "ai_rfps", "caption": "Readiness for an AI-drafted brief", "detail": "A reactor on the roof, from dark through a flicker to a full glow with a beam over it at night. It marks the categories where rules are structured enough for a request for proposal to be generated rather than written."}}, "explainer": {"opening": "Every Level 4 category in the blueprint estate is one lot of land. What stands on the lot is what the extract says about that category: whether the rules have been written, whether anybody has run a sourcing event through them, what is being spent, and whether a brief has been generated from them.", "audiences": [{"who": "If you own categories", "body": "Find your lots and read what is missing from each. A tall building with dark windows is a blueprint you have written and nobody has used. Bare ground with a hotel on it is spend with no blueprint behind it at all, and there are 89 of those."}, {"who": "If you own adoption", "body": "The card on every lot lists the markets that have taken the blueprint, and the monuments are drawn from those markets. Ask about a market by name to get its score, its rank and how many of its blueprints anybody has actually used."}, {"who": "If you own the AI agenda", "body": "The reactors mark the eight categories where the rules are already structured enough for a brief to be generated. Press N to see only those eight against the rest of the estate, and read the AI component on the scoreboard to see how little of the available credit that is."}], "ground": "The geography is the category tree. A district is a Level 2 area inside its own coloured kerb, a plot is a Level 3 group on the paler slab inside it, and a lot is one Level 4 category on one square of land. Lot area follows the average spend per category in the plot, square-root compressed: the largest plot is 400 times the smallest, so drawn literally the small end would be a single pixel. Lots stay uniform inside a plot, so an empty one is still countable as an empty one.\nStreet life is the one thing here measured per district rather than per lot. Traffic, the people on a district's own ground, and whether its streets are marked for two lanes or four all follow the district's journey score, so a district that has written its blueprints, had them used and generated briefs from them is busy, and one that has done none of it is quiet. It was spend until it became clear that spend already had the lot area and the houses, and that the journey had nothing at all at the wide view.", "caveats": [{"title": "There is no time in this data", "body": "No source carries a history, so nothing here shows change. Every figure is the position at the extract date and none of it is a trend."}, {"title": "Adoption depth is not measured", "body": "The intended adoption measure reads a constant 100% across all 145 categories, so it says nothing and nothing is bound to it. Market reach is a count with no denominator: no source states which markets a category applies to, so a category live in one market cannot be told apart from one that only ever applied to one."}, {"title": "A score is a summary, and summaries flatter", "body": "The journey score counts stages reached, not value delivered. Two categories on the same number can have arrived there by different routes, which is why the score is always shown broken into its three components and never on its own."}, {"title": "The people view ranks portfolios, not people", "body": "Nobody chose the categories they hold. A manager carrying three untouched categories scores lower than one carrying three that were already live, and that is a fact about the portfolio."}, {"title": "A category at 100 is not an autonomous category", "body": "Autonomous is the top band of a four-band scale measuring three things: a blueprint live across markets, repeated use, and briefs generated from the rules. A category at 100 has every mark this data can award. It is the end of what the extract can see, not the end of the ambition, and the one category there is proof the three things can happen together rather than proof the work is finished."}, {"title": "Monuments move, and they are capped", "body": "Assignment is recomputed at every build. A category that crosses the threshold takes a monument and one that falls below loses it, so the set will not be the same set in six months. The cap on how many exist is what keeps them worth having: without it, scores only rise and eventually every high scorer has one."}]}, "score": {"weights": {"blueprint": 40, "usage": 35, "ai": 25}, "stages": [{"id": "traditional", "from": 0, "label": "Traditional", "detail": "a blueprint exists", "detail_zero": "no blueprint yet", "means": "Anything short of a blueprint live in more than one market. The blueprint is missing, drafted, or live in a single market. Nothing in this band has ever been used, because using a blueprint once is worth 20 marks and would carry all but the emptiest lot out of it."}, {"id": "connected", "from": 40, "label": "Connected", "detail": "one blueprint, several markets", "means": "The rules are written and live in several markets, and that is all. 40 of the 100 marks are for the blueprint alone, so a category arriving here has earned every mark available for writing things down and none of the marks for anybody acting on them."}, {"id": "smart", "from": 54, "label": "Smart", "detail": "in use, and with AI", "means": "The blueprint, plus something real on top of it: a sourcing event run through it, worth 20, or a brief generated from its own rules, worth 15. This is the first band where the estate has done anything with what it wrote."}, {"id": "autonomous", "from": 75, "label": "Autonomous", "detail": "the whole journey", "detail_org": "nobody is here yet", "means": "Written, in repeated use, and generating its own briefs. Every part of the journey has happened on the same category. The organisation as a whole is nowhere near this, which is the point of showing the rail rather than a single number."}], "blueprint": [{"id": "none", "points": 0, "label": "Nothing", "stage": "none"}, {"id": "drafted", "points": 10, "label": "Drafted", "stage": "traditional"}, {"id": "live", "points": 25, "label": "Live in one market", "stage": "traditional"}, {"id": "connected", "points": 40, "label": "Live in several markets", "stage": "connected"}], "usage": [{"id": "unused", "max": 0, "points": 0, "label": "Never used"}, {"id": "once", "max": 1, "points": 20, "label": "Used once"}, {"id": "repeated", "max": null, "points": 35, "label": "Used more than once"}], "ai": [{"id": "none", "max": 0, "points": 0, "label": "No AI-generated RFPs"}, {"id": "started", "max": 1, "points": 15, "label": "First AI-generated RFP"}, {"id": "several", "max": null, "points": 25, "label": "Several AI-generated RFPs"}], "rollup": {"weight_by": "spend_eur", "transform": "sqrt", "floor_eur": 1000000}, "minimum_categories": 3}, "people": {"show": "names", "source_column": "VPC Category Manager"}, "landmarks": {"min_score": 50, "max_landmarks": 10, "label": "Landmark", "caption": "A monument replaces the building, on a lot widened to hold it", "by_market": {"UK": [{"name": "Big Ben", "shape": "clocktower"}], "Egypt": [{"name": "The Pyramids", "shape": "pyramid"}], "Italy": [{"name": "The Colosseum", "shape": "colosseum"}], "Greece": [{"name": "The Parthenon", "shape": "parthenon"}], "Germany": [{"name": "Brandenburg Gate", "shape": "gate"}, {"name": "Berlin TV Tower", "shape": "spire_sphere"}], "Turkey": [{"name": "Hagia Sophia", "shape": "dome"}], "Albania": [{"name": "Rozafa Castle", "shape": "castle"}], "Romania": [{"name": "Palace of the Parliament", "shape": "palace"}]}}, "metrics": {"blueprint_state": {"label": "Blueprint status", "description": "Whether a category blueprint exists, and whether it is live.", "kind": "categorical", "tiers": [{"id": "none", "value": "none", "label": "Empty lot", "detail": "No blueprint yet. The lot is empty ground."}, {"id": "draft", "value": "draft", "label": "Lot marked out", "detail": "Blueprint drafted. The lot is claimed but has no foundations."}, {"id": "active", "value": "active", "label": "Foundation laid", "detail": "Blueprint active. The lot can be built on."}]}, "journey_score": {"label": "Journey progress", "description": "The composite score, 0 to 100: 40 for how far the blueprint itself has got, 35 for anyone actually using it, 25 for doing it with AI. Drives building height.\nChosen over blueprint reach because reach is a count with no denominator. A category live in two of the two markets where it applies scores worse on reach than one live in five of twenty, and nothing in any source says which markets a category applies to. The score counts stages rather than markets, so a category can reach the top rung wherever it operates.\n", "unit": "points", "kind": "numeric", "tiers": [{"id": "dormant", "max": 0, "label": "Lot prepared", "detail": "No blueprint yet."}, {"id": "established", "max": 25, "label": "Small building", "detail": "Live in one market, and no further."}, {"id": "multi_market", "max": 40, "label": "Office block", "detail": "Live in several markets."}, {"id": "in_use", "max": 64, "label": "Tower", "detail": "Somebody has run a sourcing event through it."}, {"id": "advanced", "max": 84, "label": "High tower", "detail": "In repeated use, and with AI."}, {"id": "complete", "max": null, "label": "Skyscraper", "detail": "At or near the whole journey."}]}, "market_reach": {"label": "Blueprint reach", "description": "Number of local markets with a blueprint for this category. Adoption is defined as one blueprint per L4 category per local market, so this counts how widely the category has actually been taken up.\n", "unit": "markets", "kind": "numeric", "tiers": [{"id": "plot", "max": 0, "label": "Lot prepared", "detail": "No market has adopted this blueprint."}, {"id": "small", "max": 1, "label": "Small building", "detail": "Adopted in a single market."}, {"id": "block", "max": 2, "label": "Office block", "detail": "Adopted in two markets."}, {"id": "tower", "max": 4, "label": "Tower", "detail": "Adopted across three or four markets."}, {"id": "skyscraper", "max": null, "label": "Skyscraper", "detail": "Adopted across five or more markets."}]}, "ava_adoption": {"label": "AVA Sourcing adoption", "description": "Share of sourcing for this category run through AVA Sourcing.", "unit": "percent", "kind": "numeric", "tiers": [{"id": "plot", "max": 0.0, "label": "Lot prepared", "detail": "No adoption."}, {"id": "small", "max": 0.25, "label": "Small building", "detail": "Under 25% adoption."}, {"id": "block", "max": 0.5, "label": "Office block", "detail": "25 to 50% adoption."}, {"id": "tower", "max": 0.9, "label": "Tower", "detail": "50 to 90% adoption."}, {"id": "skyscraper", "max": null, "label": "Skyscraper", "detail": "Over 90% adoption."}]}, "cbp_total": {"label": "Blueprints created", "description": "Total category blueprints for this category, draft and active.", "unit": "blueprints", "kind": "numeric", "tiers": [{"id": "plot", "max": 0, "label": "Lot prepared"}, {"id": "small", "max": 1, "label": "Small building"}, {"id": "block", "max": 3, "label": "Office block"}, {"id": "tower", "max": 7, "label": "Tower"}, {"id": "skyscraper", "max": null, "label": "Skyscraper"}]}, "cbp_used": {"label": "Blueprints used", "description": "How many times a sourcing event has actually been run through this category's blueprint. Arrived in the 9 September extract. 44 categories have an active blueprint; 4 have one that has ever been used.\n", "unit": "uses", "kind": "numeric", "tiers": [{"id": "dark", "max": 0, "label": "Nobody has used it", "detail": "Built, and empty."}, {"id": "occupied", "max": 1, "label": "Used once", "detail": "Somebody has run one."}, {"id": "busy", "max": null, "label": "Used repeatedly", "detail": "In real service."}]}, "spend_eur": {"label": "Spend FY26/27", "description": "Addressable spend for the category. Thresholds are rescaled from the original deck to fit the Network distribution. Network's largest single category is €75m, so the deck's \">€100m = hotel\" rung was unreachable and 84% of categories collapsed into the bottom rung.\n", "unit": "eur", "kind": "numeric", "tiers": [{"id": "none", "max": 0, "label": "No recorded spend", "pieces": 0}, {"id": "house_1", "max": 1000000, "label": "One house", "pieces": 1}, {"id": "house_2", "max": 5000000, "label": "Two houses", "pieces": 2}, {"id": "house_3", "max": 20000000, "label": "Three houses", "pieces": 3}, {"id": "house_4", "max": 50000000, "label": "Four houses", "pieces": 4}, {"id": "hotel", "max": null, "label": "Hotel", "pieces": 5}]}, "ai_rfps": {"label": "AI-generated RFPs", "description": "Sourcing events started as AI-generated RFPs. Drives the rooftop reactor. A readiness signal only. This is not a claim that autonomous procurement is live.\nMeasured data. The column was empty in earlier extracts and carried a placeholder until then; 8 of 145 categories have any.\n", "unit": "rfps", "kind": "numeric", "tiers": [{"id": "dark", "max": 0, "label": "Dark", "detail": "No AI-generated RFP recorded."}, {"id": "flicker", "max": 1, "label": "Flicker", "detail": "One AI-generated RFP. A first attempt."}, {"id": "reactor", "max": null, "label": "Full reactor", "detail": "Repeated use. Two or more AI-generated RFPs."}]}}, "disclosure": {"show_provisional_badge": true, "show_sample_badge": true, "autonomy_note": "A readiness signal. Not a claim that autonomous procurement is live."}};
